  private void brand(){TextView mark=label("MB",34,GOLD,true);mark.setGravity(Gravity.CENTER);mark.setTypeface(Typeface.DEFAULT,Typeface.BOLD_ITALIC);mark.setBackground(shape(0xff202019,GOLD,50));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(88),dp(88));p.gravity=Gravity.CENTER;body.addView(mark,p);gap(body,16);centered(body,label("BIKI Billing PRO",28,INK,true));centered(body,label("S I G N A T U R E",12,GOLD,true));gap(body,8);centered(body,label("BIKI ONLINE SERVICE CENTER",11,MUTED,false));gap(body,22);}
  private void showLogin(){page="Login";setup(false);brand();LinearLayout p=panel();body.addView(p);p.addView(label("Welcome back.",24,INK,true));gap(p,5);p.addView(label("Sign in to your business workspace",13,MUTED,false));gap(p,18);p.addView(label("USERNAME / EMAIL",11,GOLD,true));gap(p,6);EditText email=field("Enter your cloud email",false);p.addView(email);gap(p,15);p.addView(label("PASSWORD",11,GOLD,true));gap(p,6);EditText password=field("Enter your password",true);p.addView(password);CheckBox reveal=new CheckBox(this);reveal.setText("Show password");reveal.setTextColor(MUTED);reveal.setOnCheckedChangeListener((b,on)->{password.setTransformationMethod(on?null:PasswordTransformationMethod.getInstance());password.setSelection(password.length());});p.addView(reveal);gap(p,8);TextView message=label("",12,MUTED,false);
    p.addView(action("SECURE LOGIN",true,()->{if(busy)return;String e=email.getText().toString().trim(),pw=password.getText().toString();if(e.isEmpty()||pw.isEmpty()){message.setText("Enter your cloud email and password.");return;}password.setText("");login(e,pw,message);}));gap(p,8);p.addView(message);gap(body,18);
    LinearLayout biometric=panel();LinearLayout r=row();FingerprintIcon fp=new FingerprintIcon(this);r.addView(fp,new LinearLayout.LayoutParams(dp(64),dp(64)));LinearLayout copy=column();copy.setPadding(dp(12),0,0,0);copy.addView(label("Fingerprint Login",18,GOLD,true));copy.addView(label("Unlock an authenticated session",12,MUTED,false));r.addView(copy,new LinearLayout.LayoutParams(0,-2,1));biometric.addView(r);body.addView(biometric);biometric.setOnClickListener(v->biometric());gap(body,18);centered(body,label("Native development build • read-only",12,GOLD,true));centered(body,label("No cloud records can be changed by this build.",11,MUTED,false));}
  private final class FingerprintIcon extends View{Paint p=new Paint(3);FingerprintIcon(Context c){super(c);setContentDescription("Fingerprint");}protected void onDraw(Canvas c){float x=getWidth()/2f,y=getHeight()/2f;p.setColor(GOLD);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeWidth(dp(1.8f));for(int i=0;i<5;i++){float r=dp(8+i*4);c.drawArc(x-r,y-r,x+r,y+r,180,230,false,p);}c.drawLine(x,y,x-dp(3),y+dp(17),p);}}
  private void login(String email,String password,TextView message){busy=true;message.setText("Signing in securely…");final int g=++generation;io.execute(()->{try{JSONObject payload=new JSONObject();payload.put("email",email);payload.put("password",password);payload.put("returnSecureToken",true);JSONObject auth=request("https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key="+API_KEY,"POST",payload.toString(),null);String id=auth.getString("localId"),access=auth.getString("idToken"),rt=auth.getString("refreshToken");JSONObject records=readAccounting(id,access);runOnUiThread(()->{if(g!=generation||isFinishing())return;busy=false;uid=id;token=access;refresh=rt;data=records;status="Cloud verified";locked=false;open("Home");});}catch(Exception ex){runOnUiThread(()->{if(g!=generation||isFinishing())return;busy=false;message.setText("Sign-in or cloud read failed. Check credentials, internet and account permissions.");});}});}
  private JSONObject request(String url,String method,String payload,String bearer)throws Exception{
    HttpsURLConnection c=(HttpsURLConnection)new URL(url).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(false);c.setRequestMethod(method);c.setRequestProperty("Accept","application/json");if(bearer!=null)c.setRequestProperty("Authorization","Bearer "+bearer);
    try{if(payload!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(payload.getBytes(StandardCharsets.UTF_8));}}if(c.getResponseCode()<200||c.getResponseCode()>=300)throw new IOException("HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){if(out.size()+n>3000000)throw new IOException("Response too large");out.write(buf,0,n);}return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}
  }
  private JSONObject readAccounting(String id,String access)throws Exception{JSONObject doc=request("https://firestore.googleapis.com/v1/projects/"+PROJECT+"/databases/(default)/documents/owners/"+id+"/settings/biki_accounting_v1","GET",null,access);JSONObject result=new JSONObject(doc.getJSONObject("fields").getJSONObject("value").getString("stringValue"));if(result.optJSONArray("sales")==null||result.optJSONArray("transactions")==null||result.optJSONArray("dues")==null)throw new IOException("Unrecognized record schema");return result;}
  private void refreshCloud(){if(uid.isEmpty()||busy||locked)return;busy=true;final int g=generation;final String id=uid,access=token;status="Refreshing…";open(page);io.execute(()->{try{JSONObject latest=readAccounting(id,access);runOnUiThread(()->{if(g!=generation||isFinishing())return;busy=false;data=latest;status="Cloud verified";if(!locked)open(page);});}catch(Exception e){runOnUiThread(()->{if(g!=generation||isFinishing())return;busy=false;status="Refresh failed — showing last verified data";if(!locked)open(page);});}});}
  private void biometric(){if(uid.isEmpty()||!locked){new AlertDialog.Builder(this).setTitle("Fingerprint Login").setMessage("First verify your existing cloud account using your password. This development build can unlock an active session only; it does not store login credentials.").setPositiveButton("OK",null).show();return;}if(Build.VERSION.SDK_INT<28){signOut();return;}try{new BiometricPrompt.Builder(this).setTitle("BIKI Billing PRO").setSubtitle("Unlock your business workspace").setNegativeButton("Use password",getMainExecutor(),(d,w)->signOut()).build().authenticate(new CancellationSignal(),getMainExecutor(),new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){locked=false;open("Home");}@Override public void onAuthenticationError(int n,CharSequence s){Toast.makeText(MainActivity.this,s,Toast.LENGTH_SHORT).show();}});}catch(Exception e){signOut();}}
  private void signOut(){generation++;busy=false;uid="";token="";refresh="";data=null;locked=false;status="Not connected";showLogin();}
  private void lock(){if(uid.isEmpty())return;locked=true;showLogin();}
  private void heading(String title){LinearLayout r=row();TextView back=label("‹",30,GOLD,true);back.setPadding(0,0,dp(14),0);back.setContentDescription("Back to home");back.setOnClickListener(v->open("Home"));if(!"Home".equals(title))r.addView(back);TextView t=label(title.equals("Home")?"BIKI Billing PRO":title,22,INK,true);r.addView(t,new LinearLayout.LayoutParams(0,-2,1));TextView b=label("Lock",13,GOLD,true);b.setPadding(dp(10),dp(8),0,dp(8));b.setOnClickListener(v->lock());r.addView(b);body.addView(r);gap(body,8);body.addView(label("S I G N A T U R E   •   READ ONLY",10,GOLD,true));gap(body,18);}
  private String money(double x){return NumberFormat.getCurrencyInstance(new Locale("en","IN")).format(x);}
  private String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());}
  private JSONArray arr(String k){JSONArray a=data==null?null:data.optJSONArray(k);return a==null?new JSONArray():a;}
  private double sum(JSONArray a,String field,String kind,String date){double total=0;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;if(kind!=null&&!kind.equals(o.optString("kind")))continue;if(date!=null&&!date.equals(o.optString("date")))continue;double v=o.optDouble(field,0);if(Double.isFinite(v))total+=v;}return total;}
  private void card(String title,String value,String sub,Runnable click){LinearLayout p=panel();p.addView(label(title,13,MUTED,false));gap(p,5);p.addView(label(value,25,GOLD,true));if(!sub.isEmpty()){gap(p,5);p.addView(label(sub,12,MUTED,false));}body.addView(p);if(click!=null)p.setOnClickListener(v->click.run());gap(body,10);}
  private void open(String target){if(data==null||locked){showLogin();return;}page=target;setup(true);heading(target);
    if(target.equals("Home")){body.addView(label("Business Overview",25,INK,true));body.addView(label(status,12,MUTED,false));gap(body,12);card("Today's Total Sales",money(sum(arr("sales"),"total",null,today())),"Invoice totals",()->open("Sales History"));card("Today's recorded income",money(sum(arr("transactions"),"amount","income",today())),"Not cash drawer balance",()->open("Cash Management"));card("Total outstanding due",money(sum(arr("dues"),"amount",null,null)),"Existing cloud records",()->open("Due Management"));card("Today's expense",money(sum(arr("transactions"),"amount","expense",today())),"Recorded expenses",()->open("Expense Management"));body.addView(action("Refresh cloud data",true,()->refreshCloud()));gap(body,12);body.addView(action("All app functions",false,()->open("More")));return;}
    if(target.equals("More")){for(String n:sections){body.addView(action(n,false,()->open(n)));gap(body,8);}return;}
    if(target.equals("Cloud Tools")){card("Cloud status",status,"Read-only Firebase access; no database writes",null);body.addView(action("Refresh",true,()->refreshCloud()));return;}
    if(target.equals("App Settings")||target.equals("Security & Activity Log")){body.addView(label("Native session controls",17,INK,true));gap(body,12);body.addView(action("Lock session",false,()->lock()));gap(body,10);body.addView(action("Sign out",true,()->signOut()));gap(body,12);body.addView(label("Permanent fingerprint enrollment and audit integration are pending.",13,MUTED,false));return;}
    if(target.equals("Business Reports")){card("All recorded sales",money(sum(arr("sales"),"total",null,null)),"All dates",null);card("Recorded income",money(sum(arr("transactions"),"amount","income",null)),"All dates",null);card("Recorded expenses",money(sum(arr("transactions"),"amount","expense",null)),"All dates",null);return;}
    switch(target){case "Sales History":list(arr("sales"),"customer","receiptNo","total",null);break;case "Due Management":list(arr("dues"),"name","date","amount",null);break;case "Customer Management":list(arr("customers"),"name","phone",null,null);break;case "Stock Purchase":list(arr("products"),"name","sku","selling",null);break;case "Cash Management":list(arr("transactions"),"title","date","amount",null);break;case "Expense Management":list(arr("transactions"),"title","date","amount","expense");break;case "Service Management":JSONArray a=arr("services");for(int i=0;i<a.length();i++){String t=a.optString(i,"");if(!t.isEmpty())card(t,"Service","Read only",null);}break;default:body.addView(label("This module is not yet migrated.",18,INK,true));gap(body,8);body.addView(label("Use your existing production app for this function. This development build does not open web pages or write cloud data.",14,MUTED,false));}
  }
  private void list(JSONArray a,String title,String sub,String value,String kind){int shown=0;for(int i=a.length()-1;i>=0&&shown<150;i--){JSONObject o=a.optJSONObject(i);if(o==null||(kind!=null&&!kind.equals(o.optString("kind"))))continue;shown++;LinearLayout p=panel();p.addView(label(o.optString(title,"Record"),16,INK,true));gap(p,5);p.addView(label(o.optString(sub,""),12,MUTED,false));if(value!=null){gap(p,5);p.addView(label(money(o.optDouble(value,0)),18,GOLD,true));}body.addView(p);gap(body,8);}if(shown==0)body.addView(label("No matching records in verified cloud snapshot.",14,MUTED,false));if(shown==150)body.addView(label("Latest 150 matching records shown.",12,MUTED,false));gap(body,8);body.addView(action("Refresh cloud data",false,()->refreshCloud()));}
  @Override public void onBackPressed(){if(locked||data==null){super.onBackPressed();return;}if(!page.equals("Home"))open("Home");else new AlertDialog.Builder(this).setTitle("Lock BIKI Billing?").setPositiveButton("Lock",(d,w)->lock()).setNegativeButton("Cancel",null).show();}
